<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Allow\Enable;

use Throwable;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Enable\TemplateAssetEnableAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedEnableAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(TemplateAssetEnableAllowDecision $proposal): TemplateAssetEnableAllowDecision
    {
        $this->logDebug("Check IsAuthenticatedEnableAllow Template asset");
        $span = $this->startSpan("Check IsAuthenticatedEnableAllow Template asset");
        try {
            $userContext = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (! !$userContext->anonymous) {
                    $proposal->deny('Disabled if not IsAuthenticatedEnable');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
